INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist digitale Disruption immer ein technischer Prozess?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Geschäftsmodelle betroffen"}, {"text": "Ja", "correct": false, "because": "Nicht nur Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt digitale Disruption?', 3, '[{"text": "Bestehende Märkte verändern", "correct": true, "because": "Neue Ansätze einführen"}, {"text": "Technik verbessern", "correct": false, "because": "Nur Mittel"}, {"text": "Kosten erhöhen", "correct": false, "because": "Oft Kostensenkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren treiben digitale Disruption an?', 5, '[{"text": "Neue Technologien", "correct": true, "because": "Wie KI oder Cloud"}, {"text": "Kundenbedürfnisse", "correct": true, "because": "Nachfrage steuert"}, {"text": "Hohe Preise", "correct": false, "because": "Eher Kostensenkung"}, {"text": "Weniger Innovation", "correct": false, "because": "Innovation ist Kern"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitale Disruption schafft neue Märkte. b) Sie betrifft nur IT-Firmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Branchen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse digitaler Disruption?', 4, '[{"text": "Technologische Trends", "correct": false, "because": "Treiber der Veränderung"}, {"text": "Marktveränderungen", "correct": false, "because": "Wichtige Auswirkung"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein direkter Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob digitale Disruption nur große Firmen betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs betroffen"}, {"text": "Ja", "correct": false, "because": "Größe egal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt digitale Disruption?', 3, '[{"text": "Streaming-Dienste", "correct": true, "because": "Verdrängte Videotheken"}, {"text": "Manuelle Buchhaltung", "correct": false, "because": "Kein disruptiver Wandel"}, {"text": "Papierkataloge", "correct": false, "because": "Veraltete Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branchen sind oft von Disruption betroffen?', 5, '[{"text": "Medien", "correct": true, "because": "Digitaler Wandel"}, {"text": "Einzelhandel", "correct": true, "because": "Online-Shopping"}, {"text": "Landwirtschaft", "correct": false, "because": "Weniger direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Digitale Disruption nutzt Technologie. b) Sie macht alles teurer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten oft gesenkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für digitale Disruption?', 4, '[{"text": "Innovative Ideen", "correct": false, "because": "Treiben Wandel"}, {"text": "Technologie", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Manuelle Prozesse", "correct": true, "because": "Digital ersetzt analog"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist digitale Disruption immer negativ?', 2, '[{"text": "Nein", "correct": true, "because": "Schafft Chancen"}, {"text": "Ja", "correct": false, "because": "Nicht nur Bedrohung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien fördern Disruption?', 4, '[{"text": "KI", "correct": true, "because": "Automatisiert Prozesse"}, {"text": "Cloud-Computing", "correct": true, "because": "Flexibilität"}, {"text": "Papierdokumente", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass digitale Disruption nur Startups hilft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Konzerne profitieren"}, {"text": "Ja", "correct": false, "because": "Breitere Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei digitaler Disruption?', 3, '[{"text": "Kundenfokus", "correct": true, "because": "Bedürfnisse treiben"}, {"text": "Hohe Kosten", "correct": false, "because": "Effizienz im Fokus"}, {"text": "Langsame Umsetzung", "correct": false, "because": "Schnelligkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitale Disruption verändert Geschäftsmodelle. b) Sie betrifft nur Technik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist zu eng"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen hat digitale Disruption?', 5, '[{"text": "Neue Wettbewerber", "correct": true, "because": "Markteintritt erleichtert"}, {"text": "Effizienzsteigerung", "correct": true, "because": "Prozesse optimiert"}, {"text": "Höhere Hardwarekosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei digitaler Disruption unwichtig?', 3, '[{"text": "Marktanpassung", "correct": false, "because": "Kern der Veränderung"}, {"text": "Technologie", "correct": false, "because": "Treiber"}, {"text": "Manuelle Abläufe", "correct": true, "because": "Digital ersetzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist digitale Disruption vorhersehbar?', 3, '[{"text": "Nein", "correct": true, "because": "Oft unerwartet"}, {"text": "Ja", "correct": false, "because": "Dynamik schwer planbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob digitale Disruption Arbeitsplätze nur abbaut?', 2, '[{"text": "Nein", "correct": true, "because": "Auch neue Jobs entstehen"}, {"text": "Ja", "correct": false, "because": "Nicht nur negativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für Disruption entscheidend?', 4, '[{"text": "Innovative Technologie", "correct": true, "because": "Katalysator"}, {"text": "Langsame Prozesse", "correct": false, "because": "Schnelligkeit zählt"}, {"text": "Hohe Preise", "correct": false, "because": "Effizienz im Fokus"}]');
